+async function writeRawConfig(content: string): Promise<string> {
+  const workspace = await createWorkspace({ fixture: "minimal" });
+  await fs.writeFile(workspace.configPath, content, "utf8");
+  return workspace.configPath;
+}
+
+function buildToml(
+  opts: {
+    repomixExtra?: string;
+    dedupExtra?: string;
+    configExtra?: string;
+    assetsExtra?: string;
+    sections?: string;
+  } = {},
+): string {
+  const {
+    repomixExtra = "",
+    dedupExtra = "",
+    configExtra = "",
+    assetsExtra = "",
+    sections = `[sections.src]\ninclude = ["src/**"]\nexclude = []\n`,
+  } = opts;
+
+  const parts: string[] = [
+    `schema_version = 1`,
+    `project_name = "demo"`,
+    `source_root = "."`,
+    `output_dir = "dist/demo-bundle"`,
+    ``,
+    `[repomix]`,
+    `style = "xml"`,
+    ...(repomixExtra ? [repomixExtra] : []),
+    ``,
+  ];
+
+  if (dedupExtra) {
+    parts.push(`[dedup]`, dedupExtra, ``);
+  }
+  if (configExtra) {
+    parts.push(`[config]`, configExtra, ``);
+  }
+  if (assetsExtra) {
+    parts.push(`[assets]`, assetsExtra, ``);
+  }
+
+  parts.push(sections);
+  return parts.join("\n");
+}
