+function buildSections(
+  sections: Record<string, BuildSectionOptions> | undefined,
+): Record<string, CxSectionConfig> {
+  const defaults: Record<string, BuildSectionOptions> = {
+    docs: {
+      include: ["README.md", "docs/**"],
+      exclude: [],
+    },
+    src: {
+      include: ["src/**"],
